// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler, ERC20, CoolerFactory} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    CoolerFactory factory;
    MockToken collat;
    MockToken debt;

    function setUp() public {
        c = new Cooler();
        factory = new CoolerFactory();
        collat = new MockToken("C", "C", 18);
        debt = new MockToken("D", "D", 18);
    }

    function testFuzz_property(uint256 loanID, address to_, uint256 amount) public {
        vm.assume(to_ != address(0));
        amount = bound(amount, 1, 1e24);
        uint256 l2c = 1e18;

        address cooler = factory.generateCooler(ERC20(address(collat)), ERC20(address(debt)));

        // two active requests -> two loans, so loans.length == 2
        for (uint256 i = 0; i < 2; i++) {
            collat.mint(address(this), amount);
            collat.approve(cooler, amount);
            c = Cooler(cooler);
            c.requestLoan(amount, 0, l2c, 30 days);

            debt.mint(address(this), amount);
            debt.approve(cooler, amount);
            c.clearRequest(i, false, false);
        }

        uint256 k = bound(loanID, 0, 1); // any valid loan id (always != loans.length)

        c.approveTransfer(to_, k);

        assertTrue(c.approvals(k) == to_ && c.approvals(2) == address(0));
    }
}

contract MockToken is ERC20 {
    constructor(string memory n, string memory s, uint8 d) ERC20(n, s, d) {}
    function mint(address to, uint256 amt) external { _mint(to, amt); }
}
